/**
 * banks.ts — GENERATED by `python -m ml.scripts.gen_banks_ts`. Do not edit by hand.
 *
 * Source of truth: `ml/banks.json`. The trainer reads that file; the browser runtime
 * reads this mirror, so training and inference can never disagree about question wording
 * (a mismatch here costs accuracy silently, with no error anywhere).
 *
 * banks version : 1.0.0
 * banks sha256  : cf02415d58f97f563a999960643dc27c3a1046e7b670bcdd53690d9da9a192ee
 *
 * The model answers only flat `choice` / `score` / `noul` questions, one forward pass per
 * batch of questions, and never generates text. `followups` is the adaptive stage-B tree:
 * the triage answer picks which follow-ups are worth asking, within the device's budget.
 */

export type QType = "choice" | "score" | "noul";

export interface Question {
  type: QType;
  instructions: string;
  /** choice: option key -> description · score: ordered level descriptions · noul: {false,true} relabels */
  criteria?: Record<string, string> | string[];
}

export type QuestionSet = Record<string, Question>;

export interface Bank {
  /** the key this bank is stored under in BANKS (typed as BankId after the map is defined) */
  id: string;
  title: string;
  purpose: string;
  triage: Question;
  followups: Record<string, QuestionSet>;
}

