export type BankId = keyof typeof BANKS;

export const BANK_IDS = Object.keys(BANKS) as BankId[];

/** Triage option keys for a bank — `followups` is keyed by these. */
export function triageOptions(bankId: BankId): string[] {
  const c = BANKS[bankId].triage.criteria;
  if (!c) return [];
  return Array.isArray(c) ? c.map((_, i) => String(i)) : Object.keys(c);
}

/**
 * Stage-B planner: pick at most `budget` follow-ups for the triage answer, skipping the
 * ones Tier-0 lexical evidence already proved (asking those wastes the visitor's time and
 * the device's battery for an answer we already hold).
 */
export function bankFollowups(bankId: BankId, triageKey: string, alreadyKnown: Set<string> = new Set(), budget = 3): QuestionSet {
  const pools = BANKS[bankId].followups as Record<string, QuestionSet | undefined>;
  const pool: QuestionSet = pools[triageKey] ?? {};
  const out: QuestionSet = {};
  for (const [qid, q] of Object.entries(pool)) {
    if (Object.keys(out).length >= Math.max(0, budget)) break;
    if (alreadyKnown.has(qid)) continue;
    out[qid] = q;
  }
  return out;
}

/** Total questions a bank can ever ask: 1 triage + the largest follow-up set. */
export function bankMaxQuestions(bankId: BankId): number {
  const sizes = Object.values(BANKS[bankId].followups).map((q) => Object.keys(q).length);
  return 1 + (sizes.length ? Math.max(...sizes) : 0);
}
